-- READ-ONLY: evaluates the proposed rules against existing rows (media rules for project sayqxowybxpqmqfshmqk). Returns table, id and the first failing rule only.
with r as (
  select 'dorly_listings' tbl, id rid, data d, owner::text own from public.dorly_listings
  union all select 'dorly_sellers' tbl, id rid, data d, null::text own from public.dorly_sellers
  union all select 'dorly_inquiries' tbl, id rid, data d, null::text own from public.dorly_inquiries
  union all select 'dorly_complaints' tbl, id rid, data d, null::text own from public.dorly_complaints
  union all select 'dorly_verifs' tbl, id rid, data d, null::text own from public.dorly_verifs
