  union all select 'dorly_seller_private', seller_id, data, null::text from public.dorly_seller_private
  union all select 'dorly_listing_private', listing_id, data, null::text from public.dorly_listing_private
)
select tbl, rid, case when rid is null or rid !~ '^[A-Za-z0-9_-]{1,64}$' then 'id'
  when jsonb_typeof(d) is distinct from 'object' then 'data'
  when pg_column_size(d) > 100000 then 'data size'
  when tbl = 'dorly_listings' then (case when not ((case when (d ? 'seller' and jsonb_typeof(d->'seller') <> 'null') then (jsonb_typeof(d->'seller')='string' and (d->>'seller') ~ '^[A-Za-z0-9_-]{1,64}$') else false end)) then 'seller' when not ((case when (d ? 'gen' and jsonb_typeof(d->'gen') <> 'null') then ((jsonb_typeof(d->'gen')='number' and (d->>'gen')::numeric between 1 and 40 and (d->>'gen')::numeric = trunc((d->>'gen')::numeric)) or (jsonb_typeof(d->'gen')='string' and ((d->>'gen') = any(array['2G','3G','3GS','4','4S','5','5c','5s','6','6s','7','8','SE','X','XR','XS','11','12','13','14','15','16','17','16e','17e','Air']::text[]) or (d->>'gen') ~ '^[0-9]{1,2}$'))) else false end)) then 'gen' when not ((case when (d ? 'variant' and jsonb_typeof(d->'variant') <> 'null') then (jsonb_typeof(d->'variant')='string' and (d->>'variant') = any(array['','Plus','Pro','Pro Max','mini','Max','e','2016','2020','2022']::text[])) else true end)) then 'variant' when not ((case when (d ? 'storage' and jsonb_typeof(d->'storage') <> 'null') then (jsonb_typeof(d->'storage')='string' and (d->>'storage') ~ '^[0-9]{1,4}(GB|TB)$') else false end)) then 'storage' when not ((case when (d ? 'battery' and jsonb_typeof(d->'battery') <> 'null') then (jsonb_typeof(d->'battery')='number' and (d->>'battery')::numeric between 0 and 100 and (d->>'battery')::numeric = trunc((d->>'battery')::numeric)) else false end)) then 'battery' when not ((case when (d ? 'price' and jsonb_typeof(d->'price') <> 'null') then (jsonb_typeof(d->'price')='number' and (d->>'price')::numeric between 1000 and 300000 and (d->>'price')::numeric = trunc((d->>'price')::numeric)) else false end)) then 'price' when not ((case when (d ? 'cond' and jsonb_typeof(d->'cond') <> 'null') then (jsonb_typeof(d->'cond')='string' and (d->>'cond') = any(array['excellent','vgood','good']::text[])) else false end)) then 'cond' when not ((case when (d ? 'status' and jsonb_typeof(d->'status') <> 'null') then (jsonb_typeof(d->'status')='string' and (d->>'status') = any(array['active','pending','paused','sold','rejected']::text[])) else false end)) then 'status' when not ((case when (d ? 'level' and jsonb_typeof(d->'level') <> 'null') then (jsonb_typeof(d->'level')='number' and (d->>'level')::numeric between 1 and 4 and (d->>'level')::numeric = trunc((d->>'level')::numeric)) else true end)) then 'level' when not ((case when (d ? 'color' and jsonb_typeof(d->'color') <> 'null') then (jsonb_typeof(d->'color')='string' and char_length(d->>'color') between 0 and 40) else true end)) then 'color' when not ((case when (d ? 'date' and jsonb_typeof(d->'date') <> 'null') then (jsonb_typeof(d->'date')='string' and char_length(d->>'date') between 0 and 40) else true end)) then 'date' when not ((case when (d ? 'insp' and jsonb_typeof(d->'insp') <> 'null') then (jsonb_typeof(d->'insp')='string' and char_length(d->>'insp') between 0 and 40) else true end)) then 'insp' when not ((case when (d ? 'reason' and jsonb_typeof(d->'reason') <> 'null') then (jsonb_typeof(d->'reason')='string' and char_length(d->>'reason') between 0 and 200) else true end)) then 'reason' when not ((case when (d ? 'parts' and jsonb_typeof(d->'parts') <> 'null') then (jsonb_typeof(d->'parts')='string' and char_length(d->>'parts') between 0 and 1000) else true end)) then 'parts' when not ((case when (d ? 'defects' and jsonb_typeof(d->'defects') <> 'null') then (jsonb_typeof(d->'defects')='string' and char_length(d->>'defects') between 0 and 1000) else true end)) then 'defects' when not ((case when (d ? 'warranty' and jsonb_typeof(d->'warranty') <> 'null') then (jsonb_typeof(d->'warranty')='string' and char_length(d->>'warranty') between 0 and 100) else true end)) then 'warranty' when not ((case when (d ? 'network' and jsonb_typeof(d->'network') <> 'null') then (jsonb_typeof(d->'network')='string' and char_length(d->>'network') between 0 and 100) else true end)) then 'network' when not ((case when (d ? 'acc' and jsonb_typeof(d->'acc') <> 'null') then (jsonb_typeof(d->'acc')='array' and jsonb_array_length(d->'acc') <= 4 and not exists (select 1 from jsonb_array_elements(d->'acc') e where not (jsonb_typeof(e)='string' and (e#>>'{}') = any(array['box','charger','cable','invoice']::text[])))) else true end)) then 'acc' when not ((case when (d ? 'nego' and jsonb_typeof(d->'nego') <> 'null') then (jsonb_typeof(d->'nego')='boolean') else true end) and (case when (d ? 'icloud' and jsonb_typeof(d->'icloud') <> 'null') then (jsonb_typeof(d->'icloud')='boolean') else true end) and (case when (d ? 'reviewed' and jsonb_typeof(d->'reviewed') <> 'null') then (jsonb_typeof(d->'reviewed')='boolean') else true end) and (case when (d ? 'sample' and jsonb_typeof(d->'sample') <> 'null') then (jsonb_typeof(d->'sample')='boolean') else true end) and (case when (d ? 'wa' and jsonb_typeof(d->'wa') <> 'null') then (jsonb_typeof(d->'wa')='boolean') else true end) and (case when (d ? 'pausedByAdmin' and jsonb_typeof(d->'pausedByAdmin') <> 'null') then (jsonb_typeof(d->'pausedByAdmin')='boolean') else true end)) then 'flags' when not ((case when (d ? 'pubPhotos' and jsonb_typeof(d->'pubPhotos') <> 'null') then (jsonb_typeof(d->'pubPhotos')='object' and not exists (select 1 from jsonb_each(d->'pubPhotos') e where not (e.key = any(array['front','back','sides','camera','defect']::text[]) and (jsonb_typeof(e.value)='null' or (jsonb_typeof(e.value)='string' and (e.value#>>'{}') ~ ('^https://sayqxowybxpqmqfshmqk\.supabase\.co/storage/v1/object/public/dorly-public/' || coalesce(own, '[0-9a-f-]{36}') || '/listings/' || rid || '/[A-Za-z0-9_-]{1,40}\.(jpg|png|webp)$')))))) else true end)) then 'pubPhotos' when not ((case when (d ? 'photos' and jsonb_typeof(d->'photos') <> 'null') then (jsonb_typeof(d->'photos')='array' and jsonb_array_length(d->'photos') <= 10 and not exists (select 1 from jsonb_array_elements(d->'photos') e where not (jsonb_typeof(e)='string' and (e#>>'{}') ~ ('^https://sayqxowybxpqmqfshmqk\.supabase\.co/storage/v1/object/public/dorly-public/' || coalesce(own, '[0-9a-f-]{36}') || '/listings/' || rid || '/[A-Za-z0-9_-]{1,40}\.(jpg|png|webp)$')))) else true end)) then 'photos' when not ((case when (d ? 'shots' and jsonb_typeof(d->'shots') <> 'null') then (jsonb_typeof(d->'shots')='object' and not exists (select 1 from jsonb_each(d->'shots') e where not (e.key = any(array['battery','about','storage','parts']::text[]) and (jsonb_typeof(e.value)='null' or (jsonb_typeof(e.value)='string' and (e.value#>>'{}') ~ ('^sbp:' || coalesce(own, '[0-9a-f-]{36}') || '/listings/' || rid || '/[A-Za-z0-9_-]{1,40}\.(jpg|png|webp)$')))))) else true end)) then 'shots' when not ((case when (d ? 'form' and jsonb_typeof(d->'form') <> 'null') then (jsonb_typeof(d->'form')='object') else true end)) then 'form' when not ((case when (d ? 'pay' and jsonb_typeof(d->'pay') <> 'null') then (jsonb_typeof(d->'pay')='object' and coalesce(d->'pay'->>'status','unpaid') in ('unpaid','paid')) else true end)) then 'pay' else null end)
  when tbl = 'dorly_sellers' then (case when not ((case when (d ? 'name' and jsonb_typeof(d->'name') <> 'null') then (jsonb_typeof(d->'name')='string' and char_length(d->>'name') between 1 and 80) else false end)) then 'name' when not ((case when (d ? 'type' and jsonb_typeof(d->'type') <> 'null') then (jsonb_typeof(d->'type')='string' and (d->>'type') = any(array['merchant','individual']::text[])) else false end)) then 'type' when not ((case when (d ? 'city' and jsonb_typeof(d->'city') <> 'null') then (jsonb_typeof(d->'city')='string' and char_length(d->>'city') between 0 and 160) else true end)) then 'city' when not ((case when (d ? 'badges' and jsonb_typeof(d->'badges') <> 'null') then (jsonb_typeof(d->'badges')='array' and jsonb_array_length(d->'badges') <= 5 and not exists (select 1 from jsonb_array_elements(d->'badges') e where not (jsonb_typeof(e)='string' and (e#>>'{}') = any(array['email','phone','identity','merchant','trusted']::text[])))) else true end)) then 'badges' when not ((case when (d ? 'since' and jsonb_typeof(d->'since') <> 'null') then (jsonb_typeof(d->'since')='string' and char_length(d->>'since') between 0 and 10) else true end)) then 'since' when not ((case when (d ? 'suspended' and jsonb_typeof(d->'suspended') <> 'null') then (jsonb_typeof(d->'suspended')='boolean') else true end) and (case when (d ? 'sample' and jsonb_typeof(d->'sample') <> 'null') then (jsonb_typeof(d->'sample')='boolean') else true end)) then 'flags' when not ((case when (d ? 'profile' and jsonb_typeof(d->'profile') <> 'null') then (jsonb_typeof(d->'profile')='object' and not exists (select 1 from jsonb_each(d->'profile') e where not (jsonb_typeof(e.value) in ('null','boolean') or (jsonb_typeof(e.value)='string' and char_length(e.value#>>'{}') <= 500)))) else true end)) then 'profile' when not ((case when (d ? 'profile' and jsonb_typeof(d->'profile') <> 'null') then (coalesce(d->'profile'->>'web','') = '' or ((d->'profile'->>'web') ~ '^https?://[^\s"<>]+$' and char_length(d->'profile'->>'web') <= 300)) else true end)) then 'profile.web' else null end)
  when tbl = 'dorly_inquiries' then (case when not ((case when (d ? 'seller' and jsonb_typeof(d->'seller') <> 'null') then (jsonb_typeof(d->'seller')='string' and (d->>'seller') ~ '^[A-Za-z0-9_-]{1,64}$') else false end)) then 'seller' when not ((case when (d ? 'listing' and jsonb_typeof(d->'listing') <> 'null') then (jsonb_typeof(d->'listing')='string' and (d->>'listing') ~ '^[A-Za-z0-9_-]{1,64}$') else true end)) then 'listing' when not ((case when (d ? 'name' and jsonb_typeof(d->'name') <> 'null') then (jsonb_typeof(d->'name')='string' and char_length(d->>'name') between 0 and 80) else true end)) then 'name' when not ((case when (d ? 'phone' and jsonb_typeof(d->'phone') <> 'null') then (jsonb_typeof(d->'phone')='string' and char_length(d->>'phone') between 0 and 30) else true end)) then 'phone' when not ((case when (d ? 'msg' and jsonb_typeof(d->'msg') <> 'null') then (jsonb_typeof(d->'msg')='string' and char_length(d->>'msg') between 0 and 2000) else true end)) then 'msg' when not ((case when (d ? 'time' and jsonb_typeof(d->'time') <> 'null') then (jsonb_typeof(d->'time')='string' and char_length(d->>'time') between 0 and 40) else true end)) then 'time' when not ((case when (d ? 'status' and jsonb_typeof(d->'status') <> 'null') then (jsonb_typeof(d->'status')='string' and (d->>'status') = any(array['new','read']::text[])) else false end)) then 'status' when not ((case when (d ? 'sample' and jsonb_typeof(d->'sample') <> 'null') then (jsonb_typeof(d->'sample')='boolean') else true end)) then 'flags' else null end)
  when tbl = 'dorly_complaints' then (case when not ((case when (d ? 'against' and jsonb_typeof(d->'against') <> 'null') then (jsonb_typeof(d->'against')='string' and (d->>'against') ~ '^[A-Za-z0-9_-]{1,64}$') else true end)) then 'against' when not ((case when (d ? 'by' and jsonb_typeof(d->'by') <> 'null') then (jsonb_typeof(d->'by')='string' and char_length(d->>'by') between 0 and 80) else true end)) then 'by' when not ((case when (d ? 'text' and jsonb_typeof(d->'text') <> 'null') then (jsonb_typeof(d->'text')='string' and char_length(d->>'text') between 0 and 2000) else true end)) then 'text' when not ((case when (d ? 'status' and jsonb_typeof(d->'status') <> 'null') then (jsonb_typeof(d->'status')='string' and (d->>'status') = any(array['open','resolved']::text[])) else false end)) then 'status' when not ((case when (d ? 'sample' and jsonb_typeof(d->'sample') <> 'null') then (jsonb_typeof(d->'sample')='boolean') else true end)) then 'flags' else null end)
  when tbl = 'dorly_verifs' then (case when not ((case when (d ? 'seller' and jsonb_typeof(d->'seller') <> 'null') then (jsonb_typeof(d->'seller')='string' and (d->>'seller') ~ '^[A-Za-z0-9_-]{1,64}$') else false end)) then 'seller' when not ((case when (d ? 'kind' and jsonb_typeof(d->'kind') <> 'null') then (jsonb_typeof(d->'kind')='string' and (d->>'kind') = any(array['merchant','identity']::text[])) else false end)) then 'kind' when not ((case when (d ? 'status' and jsonb_typeof(d->'status') <> 'null') then (jsonb_typeof(d->'status')='string' and (d->>'status') = any(array['pending','approved','rejected']::text[])) else false end)) then 'status' when not ((case when (d ? 'reason' and jsonb_typeof(d->'reason') <> 'null') then (jsonb_typeof(d->'reason')='string' and char_length(d->>'reason') between 0 and 200) else true end)) then 'reason' when not ((case when (d ? 'time' and jsonb_typeof(d->'time') <> 'null') then (jsonb_typeof(d->'time')='string' and char_length(d->>'time') between 0 and 40) else true end)) then 'time' when not ((case when (d ? 'docs' and jsonb_typeof(d->'docs') <> 'null') then (jsonb_typeof(d->'docs')='array' and jsonb_array_length(d->'docs') <= 10 and not exists (select 1 from jsonb_array_elements(d->'docs') x where not (jsonb_typeof(x)='object' and coalesce(jsonb_typeof(x->'label'),'string')='string' and char_length(coalesce(x->>'label','')) <= 200 and coalesce(jsonb_typeof(x->'name'),'string')='string' and char_length(coalesce(x->>'name','')) <= 255))) else true end)) then 'docs' when not ((case when (d ? 'sample' and jsonb_typeof(d->'sample') <> 'null') then (jsonb_typeof(d->'sample')='boolean') else true end)) then 'flags' else null end)
  when tbl = 'dorly_audit' then (case when not ((case when (d ? 't' and jsonb_typeof(d->'t') <> 'null') then (jsonb_typeof(d->'t')='number') else true end)) then 't' when not ((case when (d ? 'by' and jsonb_typeof(d->'by') <> 'null') then (jsonb_typeof(d->'by')='string' and char_length(d->>'by') between 0 and 80) else true end)) then 'by' when not ((case when (d ? 'txt' and jsonb_typeof(d->'txt') <> 'null') then (jsonb_typeof(d->'txt')='string' and char_length(d->>'txt') between 0 and 1000) else true end)) then 'txt' else null end)
